// Model Context Protocol (minimal)
// A tiny MCP-style client/server pair. The server advertises tools and
// resources; the client discovers their schemas over a message channel and
// invokes them via JSON-RPC-like request/response messages.

interface RpcRequest {
  id: number;
  method: string;
  params?: Record<string, any>;
}

interface RpcResponse {
  id: number;
  result?: any;
  error?: string;
}

interface ToolDef {
  name: string;
  description: string;
  inputSchema: Record<string, string>;
  handler: (args: Record<string, any>) => any;
}

interface ResourceDef {
  uri: string;
  name: string;
  read: () => string;
}

// Channel abstraction: in a real deployment this is stdio or a socket.
class McpServer {
  private tools = new Map<string, ToolDef>();
  private resources = new Map<string, ResourceDef>();

  registerTool(tool: ToolDef): void { this.tools.set(tool.name, tool); }
  registerResource(res: ResourceDef): void { this.resources.set(res.uri, res); }

  handle(req: RpcRequest): RpcResponse {
    try {
      switch (req.method) {
        case 'tools/list':
          return { id: req.id, result: [...this.tools.values()].map(t => ({
            name: t.name, description: t.description, inputSchema: t.inputSchema,
          })) };
        case 'tools/call': {
          const tool = this.tools.get(req.params?.name);
          if (!tool) throw new Error(`No such tool: ${req.params?.name}`);
          return { id: req.id, result: tool.handler(req.params?.arguments || {}) };
        }
        case 'resources/list':
          return { id: req.id, result: [...this.resources.values()].map(r => ({ uri: r.uri, name: r.name })) };
        case 'resources/read': {
          const res = this.resources.get(req.params?.uri);
          if (!res) throw new Error(`No such resource: ${req.params?.uri}`);
          return { id: req.id, result: { uri: res.uri, contents: res.read() } };
        }
        default:
          throw new Error(`Unknown method: ${req.method}`);
      }
    } catch (e) {
      return { id: req.id, error: (e as Error).message };
    }
  }
}

class McpClient {
  private seq = 0;
  private server: McpServer;

  constructor(server: McpServer) {
    this.server = server;
  }

  private call(method: string, params?: Record<string, any>): any {
    const req: RpcRequest = { id: ++this.seq, method, params };
    const res = this.server.handle(req);
    if (res.error) throw new Error(res.error);
    return res.result;
  }

  listTools(): any[] { return this.call('tools/list'); }
  callTool(name: string, args: Record<string, any>): any { return this.call('tools/call', { name, arguments: args }); }
  listResources(): any[] { return this.call('resources/list'); }
  readResource(uri: string): any { return this.call('resources/read', { uri }); }
}

function main() {
  const server = new McpServer();
  server.registerTool({
    name: 'add', description: 'Add two integers',
    inputSchema: { a: 'number', b: 'number' },
    handler: ({ a, b }) => a + b,
  });
  server.registerTool({
    name: 'get_weather', description: 'Return canned weather for a city',
    inputSchema: { city: 'string' },
    handler: ({ city }) => ({ city, tempC: 21, sky: 'clear' }),
  });
  server.registerResource({
    uri: 'file:///readme.txt', name: 'Project README',
    read: () => 'This project demonstrates the Model Context Protocol.',
  });

  const client = new McpClient(server);

  console.log('Discovered tools:');
  for (const t of client.listTools()) {
    console.log(`  ${t.name}(${Object.keys(t.inputSchema).join(', ')}) - ${t.description}`);
  }

  console.log('\nInvoking tools:');
  console.log(`  add(2, 40) = ${JSON.stringify(client.callTool('add', { a: 2, b: 40 }))}`);
  console.log(`  get_weather("Paris") = ${JSON.stringify(client.callTool('get_weather', { city: 'Paris' }))}`);

  console.log('\nResources:');
  for (const r of client.listResources()) console.log(`  ${r.uri} (${r.name})`);
  const doc = client.readResource('file:///readme.txt');
  console.log(`  read ${doc.uri}: "${doc.contents}"`);

  console.log('\nError handling:');
  try { client.callTool('divide', { a: 1, b: 0 }); } catch (e) { console.log(`  ${(e as Error).message}`); }
}

main();

